			CacheDir:           filepath.Join(homeDir, ".devdesk", "cache", "scans"),
			MaxCachedReports:   50,
			Timeout:            300, // 5 minutes
			MaxConcurrentScans: 3,
			EnableVuln:         true,
			EnableSecret:       true,
			BaseImageTrack:     BaseImageTrackSameLine,
		},
		MCP: MCPConfig{
