	inline := strings.Replace(webDeployment, "securityContext:\n            privileged: true", "securityContext: {}", 1)
	sysAdmin := strings.Replace(webDeployment, "privileged: true", "capabilities:\n              add: [SYS_ADMIN]", 1)
